export function culturalMonthKey(date: string) {
  return date.slice(0, 7); // YYYY-MM
}

export function formatCulturalDate(date: string) {
  const d = new Date(`${date}T12:00:00`);
  return d.toLocaleDateString("en-CA", {
    weekday: "short",
    year: "numeric",
    month: "short",
    day: "numeric",
  });
}

